FUNCTION_BLOCK FB
VAR_INPUT
    enqueue   : BOOL;
    dequeue   : BOOL;
    reset     : BOOL;
    capacity  : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head         : DINT := 1;
    tail         : DINT := 1;
    count        : DINT := 0;
    enqueuePrev  : BOOL := FALSE;
    dequeuePrev  : BOOL := FALSE;
    enqueueRising: BOOL;
    dequeueRising: BOOL;
END_VAR

// Reset handling
IF reset THEN
    count := 0;
    head  := 1;
    tail  := 1;
    status := 16#0000;

    // Capture current input state to avoid false edges after reset
    enqueuePrev  := enqueue;
    dequeuePrev  := dequeue;
ELSE
    // Detect rising edges
    enqueueRising  := enqueue AND NOT enqueuePrev;
    dequeueRising  := dequeue AND NOT dequeuePrev;

    // Process enqueue request
    IF enqueueRising THEN
        IF count < capacity THEN
            // Append item to tail
            buffer[tail] := item;
            tail := tail + 1;
            IF tail > capacity THEN
                tail := 1;
            END_IF;
            count := count + 1;
            status := 16#0000;
        ELSE
            // Queue full – reject
            status := 16#8002;
        END_IF
    // Process dequeue request
    ELSIF dequeueRising THEN
        IF count > 0 THEN
            // Remove front element and return it in item
            item := buffer[head];
            head := head + 1;
            IF head > capacity THEN
                head := 1;
            END_IF;
            count := count - 1;
            status := 16#0000;
        ELSE
            // Queue empty – reject
            status := 16#8001;
        END_IF
    ELSE
        // No request this cycle
        status := 16#0000;
    END_IF

    // Update edge detection history
    enqueuePrev := enqueue;
    dequeuePrev := dequeue;
END_IF

// Expose current fill level
elementCount := count;

END_FUNCTION_BLOCK
